insert into ops.scac_mutation_registry_entry(registry_version,ingress_key,ingress_kind,effect_class,source_locator,entry_digest,contract)
select 'scac-mutation-registry.v9',contract->>'ingress_key',contract->>'ingress_kind',contract->>'effect_class',contract->>'source_locator',
  'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(contract-'entry_digest'),'UTF8'),'sha256'),'hex'),contract-'entry_digest' from seed;

-- Exact database capability rows are projected from the just-built catalog.
-- The sealed expected category digests are independently recomputed by the DB gate.
with recursive connected(oid) as (
  select oid from pg_roles where rolname~'^carr_' and rolname<>'carr_ci' union
  select other.oid from connected c join pg_auth_members m on m.roleid=c.oid or m.member=c.oid join pg_roles other on other.oid=case when m.roleid=c.oid then m.member else m.roleid end where other.rolname<>'carr_ci' and not other.rolsuper
), runtime_roles as (select r.oid,r.rolname from pg_roles r where r.oid in(select oid from connected) and not r.rolsuper
), functions as (
  select p.oid,n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args,p.prosecdef,p.prokind,p.provolatile,p.proparallel,p.proconfig,p.proacl,p.proowner
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname not in ('pg_catalog','information_schema') and p.prokind in ('f','p')
), capabilities as (
  select f.*,acl.grantee,acl.privilege_type,acl.is_grantable from functions f
  cross join lateral aclexplode(coalesce(f.proacl,acldefault('f',f.proowner))) acl
), observed as (
  select jsonb_build_object('ingress_key','db-function-acl:'||nspname||'.'||proname||'('||args||'):'||coalesce(r.rolname,'public')||':execute',
    'ingress_kind','db_function_acl','signature',nspname||'.'||proname||'('||args||')','security_definer',prosecdef,
    'function_kind',prokind,'volatility',provolatile,'parallel',proparallel,'config',coalesce(to_jsonb(proconfig),'[]'::jsonb),
    'grantee',coalesce(r.rolname,'public'),'privilege','execute','grantable',is_grantable) row
  from capabilities c left join pg_roles r on r.oid=c.grantee
  where prosecdef and privilege_type='EXECUTE' and grantee<>proowner and (grantee=0 or r.oid in(select oid from runtime_roles))
), contracts as (
  select row||jsonb_build_object('effect_class','administrative_mutation','owner_package','11','implementation_state','inventoried_not_atomically_mediated','classification_authorizing',false,'source_locator',row->>'signature') contract from observed
)
insert into ops.scac_mutation_registry_entry(registry_version,ingress_key,ingress_kind,effect_class,source_locator,entry_digest,contract)
select 'scac-mutation-registry.v9',contract->>'ingress_key',contract->>'ingress_kind',contract->>'effect_class',contract->>'source_locator',
  'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(contract),'UTF8'),'sha256'),'hex'),contract from contracts;

with recursive connected(oid) as (select oid from pg_roles where rolname~'^carr_' and rolname<>'carr_ci' union select other.oid from connected c join pg_auth_members m on m.roleid=c.oid or m.member=c.oid join pg_roles other on other.oid=case when m.roleid=c.oid then m.member else m.roleid end where other.rolname<>'carr_ci' and not other.rolsuper), runtime_roles as (select r.oid,r.rolname from pg_roles r where r.oid in(select oid from connected) and not r.rolsuper), capabilities as (
  select n.nspname,c.relname,c.relkind,c.relowner,acl.grantee,acl.privilege_type,acl.is_grantable
  from pg_class c join pg_namespace n on n.oid=c.relnamespace
  cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) acl
  where n.nspname not in ('pg_catalog','information_schema') and c.relkind in ('r','p','v','m','f')
), observed as (
  select jsonb_build_object('ingress_key','db-relation-acl:'||nspname||'.'||relname||':'||coalesce(r.rolname,'public')||':'||lower(privilege_type),
    'ingress_kind','db_relation_acl','relation',nspname||'.'||relname,'relation_kind',relkind,'grantee',coalesce(r.rolname,'public'),
    'privilege',lower(privilege_type),'grantable',is_grantable) row
  from capabilities c left join pg_roles r on r.oid=c.grantee
  where privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE') and grantee<>relowner and (grantee=0 or r.oid in(select oid from runtime_roles))
), contracts as (
  select row||jsonb_build_object('effect_class','administrative_mutation','owner_package','11','implementation_state','inventoried_not_atomically_mediated','classification_authorizing',false,'source_locator',row->>'relation') contract from observed
)
insert into ops.scac_mutation_registry_entry(registry_version,ingress_key,ingress_kind,effect_class,source_locator,entry_digest,contract)
select 'scac-mutation-registry.v9',contract->>'ingress_key',contract->>'ingress_kind',contract->>'effect_class',contract->>'source_locator',
  'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(contract),'UTF8'),'sha256'),'hex'),contract from contracts;

with recursive connected(oid) as (select oid from pg_roles where rolname~'^carr_' and rolname<>'carr_ci' union select other.oid from connected c join pg_auth_members m on m.roleid=c.oid or m.member=c.oid join pg_roles other on other.oid=case when m.roleid=c.oid then m.member else m.roleid end where other.rolname<>'carr_ci' and not other.rolsuper), runtime_roles as (select r.oid,r.rolname from pg_roles r where r.oid in(select oid from connected) and not r.rolsuper), capabilities as (
  select n.nspname,c.relname,c.relkind,c.relowner,a.attname,acl.grantee,acl.privilege_type,acl.is_grantable
  from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace
  cross join lateral aclexplode(a.attacl) acl
  where a.attnum>0 and not a.attisdropped and a.attacl is not null and cardinality(a.attacl)>0
    and n.nspname not in ('pg_catalog','information_schema') and c.relkind in ('r','p','v','m','f')
), observed as (
  select jsonb_build_object('ingress_key','db-column-acl:'||nspname||'.'||relname||'.'||attname||':'||coalesce(r.rolname,'public')||':'||lower(privilege_type),
    'ingress_kind','db_column_acl','relation',nspname||'.'||relname,'relation_kind',relkind,'column',attname,
    'grantee',coalesce(r.rolname,'public'),'privilege',lower(privilege_type),'grantable',is_grantable) row
  from capabilities c left join pg_roles r on r.oid=c.grantee
  where privilege_type in ('INSERT','UPDATE') and grantee<>relowner and (grantee=0 or r.oid in(select oid from runtime_roles))
), contracts as (
  select row||jsonb_build_object('effect_class','administrative_mutation','owner_package','11','implementation_state','inventoried_not_atomically_mediated','classification_authorizing',false,'source_locator',(row->>'relation')||'.'||(row->>'column')) contract from observed
)
insert into ops.scac_mutation_registry_entry(registry_version,ingress_key,ingress_kind,effect_class,source_locator,entry_digest,contract)
select 'scac-mutation-registry.v9',contract->>'ingress_key',contract->>'ingress_kind',contract->>'effect_class',contract->>'source_locator',
  'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(contract),'UTF8'),'sha256'),'hex'),contract from contracts;

do $$ declare actual_count integer; actual_digest text; expected jsonb; category text; kind text;
begin
  for category,kind in values ('secdef_execute','db_function_acl'),('relation_dml','db_relation_acl'),('column_dml','db_column_acl') loop
    select count(*),'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(coalesce(jsonb_agg(contract-'effect_class'-'owner_package'-'implementation_state'-'classification_authorizing'-'source_locator' order by ingress_key collate "C", ops.scac_canonical_json(contract-'effect_class'-'owner_package'-'implementation_state'-'classification_authorizing'-'source_locator') collate "C"),'[]'::jsonb)),'UTF8'),'sha256'),'hex')
      into actual_count,actual_digest from ops.scac_mutation_registry_entry where registry_version='scac-mutation-registry.v9' and ingress_kind=kind;
    select catalog_projection->category into expected from ops.scac_mutation_registry_version where registry_version='scac-mutation-registry.v9';
    if actual_count<>(expected->>'count')::integer or actual_digest<>expected->>'digest' then raise exception 'SCAC v9 database catalog category % drifted: count %, digest %',category,actual_count,actual_digest; end if;
  end loop;
end $$;

update ops.scac_mutation_registry_version v set entry_set_digest=(select 'sha256:'||encode(public.digest(convert_to(string_agg(e.entry_digest,',' order by e.ingress_key collate "C"),'UTF8'),'sha256'),'hex') from ops.scac_mutation_registry_entry e where e.registry_version=v.registry_version) where registry_version='scac-mutation-registry.v9';
do $$ begin
  if (select count(*) from ops.scac_mutation_registry_entry where registry_version='scac-mutation-registry.v9')<>1439
     or exists(select 1 from ops.scac_mutation_registry_entry where registry_version='scac-mutation-registry.v9' and (contract->>'owner_package'<>'11' or (contract->>'classification_authorizing')::boolean))
     or exists(select 1 from ops.scac_mutation_registry_entry where registry_version='scac-mutation-registry.v9' and entry_digest is distinct from 'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(contract),'UTF8'),'sha256'),'hex')) then raise exception 'SCAC mutation registry v9 seed is incomplete or drifted'; end if;
  if (select registry_digest from ops.scac_mutation_registry_version where registry_version='scac-mutation-registry.v8')<>'sha256:56edcf25393a1c7b47985b9e2a272a8e7fcf0930709147ae823ca9b15290212e'
     or (select count(*) from ops.scac_mutation_registry_entry where registry_version='scac-mutation-registry.v8')<>1425 then raise exception 'sealed SCAC mutation registry v8 changed during successor creation'; end if;
end $$;
-- Retain the already-sealed v3 metadata lookup; v4 live and seal predicates remain separate below.
create or replace function ops.scac_mutation_catalog_v3_current()
returns boolean language sql stable security definer set search_path=pg_catalog,ops as $fn$
  select exists(select 1 from ops.scac_mutation_registry_version
    where registry_version='scac-mutation-registry.v3'
      and registry_digest='sha256:ace611250aaf2ffd7b96ca3195d20e9dc2697bbea555eadc7c661407e838cae7'
      and entry_count=1395 and source_entry_count=800)
$fn$;
comment on function ops.scac_mutation_catalog_v3_current() is 'Historical v3 seal availability after v9; it is not a claim that the live catalog remains v3.';

create or replace function ops.scac_mutation_registry_seal_valid(p_registry_version text)
returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,ops as $fn$
declare v ops.scac_mutation_registry_version%rowtype; actual_count integer; actual_source_count integer;
        actual_set text; bad_hash boolean; category text; kind text; expected_registry text;
        actual_category_count integer; actual_category_digest text; expected jsonb; expected_catalog jsonb;
begin
  if p_registry_version not in ('scac-mutation-registry.v1','scac-mutation-registry.v2','scac-mutation-registry.v3','scac-mutation-registry.v4','scac-mutation-registry.v5','scac-mutation-registry.v6','scac-mutation-registry.v7','scac-mutation-registry.v8') then return false; end if;
  expected_registry:=case p_registry_version
    when 'scac-mutation-registry.v1' then 'sha256:7cc2feacec82bf7cce2af9af309dc4ae9426922003471703af010f6728957190'
    when 'scac-mutation-registry.v2' then 'sha256:6dc9f8353712e0f9ee9dcbc96d05b802631e420cfa698944c2b6401a11c6a9ff'
    when 'scac-mutation-registry.v3' then 'sha256:ace611250aaf2ffd7b96ca3195d20e9dc2697bbea555eadc7c661407e838cae7'
    when 'scac-mutation-registry.v4' then 'sha256:32b9edaf4e718cfa55f87cc6b650f97480a09f00fbde35c10f1e5e23bc6eaa4c'
    when 'scac-mutation-registry.v5' then 'sha256:314a4b108eaded1a00b7f604af93d44838b615fab79820d1a2c9d9d4b08fa6ca'
    when 'scac-mutation-registry.v6' then 'sha256:afd27c13b68423dcaaeafc68c0c1ddc018452ef8d9e7cad5bb32cac4327d80d7'
    when 'scac-mutation-registry.v7' then 'sha256:405a1bd7aa421b16ebd3d3fe7422a2525826dba563dffeb2dad5a6b90d12859b'
    when 'scac-mutation-registry.v8' then 'sha256:56edcf25393a1c7b47985b9e2a272a8e7fcf0930709147ae823ca9b15290212e' end;
  expected_catalog:=case p_registry_version
    when 'scac-mutation-registry.v1' then '{"projection_version":"scac-db-catalog-projection.v1","secdef_execute":{"count":290,"digest":"sha256:92d1347b45ee669c97a8b21712684651ee67aa3a2af363fca7c3f3a25436a0b6"},"relation_dml":{"count":285,"digest":"sha256:53d12ebf83db4661b0e55eb81f91ab510c34828424a2b945b66c0286134b0b0b"},"column_dml":{"count":12,"digest":"sha256:607e31d990653776243350d001ca465234e321349b05259751f8231ae3c2c44f"}}'::jsonb
    when 'scac-mutation-registry.v2' then '{"projection_version":"scac-db-catalog-projection.v2","secdef_execute":{"count":294,"digest":"sha256:8e1f8ed8984bc1f1a627020d1b5b0384124c5e5adba79ac17df0b21702bf6cc5"},"relation_dml":{"count":285,"digest":"sha256:53d12ebf83db4661b0e55eb81f91ab510c34828424a2b945b66c0286134b0b0b"},"column_dml":{"count":12,"digest":"sha256:607e31d990653776243350d001ca465234e321349b05259751f8231ae3c2c44f"},"role_authority":{"count":12,"digest":"sha256:eb650de73032466b46787f4a5826b60b100591657489a7990d9161e2d6588648"}}'::jsonb
    when 'scac-mutation-registry.v3' then '{"projection_version":"scac-db-catalog-projection.v3","secdef_execute":{"count":298,"digest":"sha256:d8306fc5bb4bd3348fe5197f0946c251c4f0486ecdf98914ba11a7af6e4682c5"},"relation_dml":{"count":285,"digest":"sha256:53d12ebf83db4661b0e55eb81f91ab510c34828424a2b945b66c0286134b0b0b"},"column_dml":{"count":12,"digest":"sha256:607e31d990653776243350d001ca465234e321349b05259751f8231ae3c2c44f"},"role_authority":{"count":12,"digest":"sha256:eb650de73032466b46787f4a5826b60b100591657489a7990d9161e2d6588648"}}'::jsonb
    when 'scac-mutation-registry.v4' then '{"projection_version":"scac-db-catalog-projection.v4","secdef_execute":{"count":302,"digest":"sha256:abe2fb9009736fa4ae47270fcf5d2153bbf3e7a8ed01de861cced9a1bb2fee82"},"relation_dml":{"count":285,"digest":"sha256:53d12ebf83db4661b0e55eb81f91ab510c34828424a2b945b66c0286134b0b0b"},"column_dml":{"count":12,"digest":"sha256:607e31d990653776243350d001ca465234e321349b05259751f8231ae3c2c44f"},"role_authority":{"count":12,"digest":"sha256:eb650de73032466b46787f4a5826b60b100591657489a7990d9161e2d6588648"}}'::jsonb
    when 'scac-mutation-registry.v5' then '{"projection_version":"scac-db-catalog-projection.v5","secdef_execute":{"count":307,"digest":"sha256:d4671fbc10a54406acece348dbeaef08b044b8231037bf4ecce8e1d85cd2d24d"},"relation_dml":{"count":285,"digest":"sha256:53d12ebf83db4661b0e55eb81f91ab510c34828424a2b945b66c0286134b0b0b"},"column_dml":{"count":12,"digest":"sha256:607e31d990653776243350d001ca465234e321349b05259751f8231ae3c2c44f"},"role_authority":{"count":12,"digest":"sha256:eb650de73032466b46787f4a5826b60b100591657489a7990d9161e2d6588648"}}'::jsonb
    when 'scac-mutation-registry.v6' then '{"projection_version":"scac-db-catalog-projection.v6","secdef_execute":{"count":311,"digest":"sha256:78771a23004af05b61ea9491ed70248ee8cbbe77aa6ace8c6f0437983624470b"},"relation_dml":{"count":285,"digest":"sha256:53d12ebf83db4661b0e55eb81f91ab510c34828424a2b945b66c0286134b0b0b"},"column_dml":{"count":12,"digest":"sha256:607e31d990653776243350d001ca465234e321349b05259751f8231ae3c2c44f"},"role_authority":{"count":12,"digest":"sha256:eb650de73032466b46787f4a5826b60b100591657489a7990d9161e2d6588648"}}'::jsonb
    when 'scac-mutation-registry.v7' then '{"projection_version":"scac-db-catalog-projection.v7","secdef_execute":{"count":315,"digest":"sha256:d47181d79ffb352fdf2c707a6fa265f093a8c7edde76df4358a6805c89651022"},"relation_dml":{"count":285,"digest":"sha256:53d12ebf83db4661b0e55eb81f91ab510c34828424a2b945b66c0286134b0b0b"},"column_dml":{"count":12,"digest":"sha256:607e31d990653776243350d001ca465234e321349b05259751f8231ae3c2c44f"},"role_authority":{"count":12,"digest":"sha256:eb650de73032466b46787f4a5826b60b100591657489a7990d9161e2d6588648"}}'::jsonb
    when 'scac-mutation-registry.v8' then '{"projection_version":"scac-db-catalog-projection.v8","secdef_execute":{"count":328,"digest":"sha256:7c6a54dda8f8c4c6f4fcb6004f2544ba8231f212e1b2d8e5c9cc39651a2a216c"},"relation_dml":{"count":285,"digest":"sha256:53d12ebf83db4661b0e55eb81f91ab510c34828424a2b945b66c0286134b0b0b"},"column_dml":{"count":12,"digest":"sha256:607e31d990653776243350d001ca465234e321349b05259751f8231ae3c2c44f"},"role_authority":{"count":12,"digest":"sha256:eb650de73032466b46787f4a5826b60b100591657489a7990d9161e2d6588648"}}'::jsonb end;
  select * into v from ops.scac_mutation_registry_version where registry_version=p_registry_version;
  if v.registry_version is null or v.registry_digest is distinct from expected_registry or
     v.catalog_projection is distinct from expected_catalog then return false; end if;
  select count(*),count(*) filter(where ingress_kind not in ('db_function_acl','db_relation_acl','db_column_acl')),
    'sha256:'||encode(public.digest(convert_to(coalesce(string_agg(entry_digest,',' order by ingress_key collate "C", entry_digest collate "C"),''),'UTF8'),'sha256'),'hex'),
    coalesce(bool_or(entry_digest is distinct from 'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(contract),'UTF8'),'sha256'),'hex')),false)
    into actual_count,actual_source_count,actual_set,bad_hash
    from ops.scac_mutation_registry_entry where registry_version=p_registry_version;
  if actual_count<>v.entry_count or actual_source_count<>v.source_entry_count or
     actual_set is distinct from v.entry_set_digest or bad_hash then return false; end if;
  for category,kind in values ('secdef_execute','db_function_acl'),('relation_dml','db_relation_acl'),('column_dml','db_column_acl') loop
    select count(*),'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(coalesce(jsonb_agg(contract-'effect_class'-'owner_package'-'implementation_state'-'classification_authorizing'-'source_locator' order by ingress_key collate "C", ops.scac_canonical_json(contract-'effect_class'-'owner_package'-'implementation_state'-'classification_authorizing'-'source_locator') collate "C"),'[]'::jsonb)),'UTF8'),'sha256'),'hex')
      into actual_category_count,actual_category_digest from ops.scac_mutation_registry_entry
      where registry_version=p_registry_version and ingress_kind=kind;
    expected:=v.catalog_projection->category;
    if actual_category_count<>(expected->>'count')::integer or actual_category_digest<>expected->>'digest' then return false; end if;
  end loop;
  return true;
end $fn$;
create or replace function ops.scac_mutation_registry_v4_seal_available()
returns boolean language sql stable security definer set search_path=pg_catalog,ops as $fn$
  select ops.scac_mutation_registry_seal_valid('scac-mutation-registry.v4')
$fn$;
create or replace function ops.scac_mutation_catalog_v4_current()
returns boolean language sql stable security definer set search_path=pg_catalog,ops as $fn$
  select ops.scac_mutation_catalog_v4_live_at_seal()
$fn$;
comment on function ops.scac_mutation_registry_v4_seal_available() is 'Exact immutable v4 registry seal; separate from whether the live catalog still equals v4.';
comment on function ops.scac_mutation_catalog_v4_current() is 'Historical v4 live-catalog validator; expected to become false after the v9 authority surface is installed.';
revoke all on function ops.scac_mutation_registry_seal_valid(text),ops.scac_mutation_registry_v4_seal_available(),
  ops.scac_mutation_catalog_v4_live_at_seal(),ops.scac_mutation_catalog_v4_current()
  from public,carr_reader,carr_writer,carr_jobs,carr_authority;
do $history$ declare expected record; actual ops.scac_mutation_registry_version%rowtype;
begin
  for expected in select * from (values
    ('scac-mutation-registry.v1','sha256:7cc2feacec82bf7cce2af9af309dc4ae9426922003471703af010f6728957190',1387,800),
    ('scac-mutation-registry.v2','sha256:6dc9f8353712e0f9ee9dcbc96d05b802631e420cfa698944c2b6401a11c6a9ff',1391,800),
    ('scac-mutation-registry.v3','sha256:ace611250aaf2ffd7b96ca3195d20e9dc2697bbea555eadc7c661407e838cae7',1395,800),
    ('scac-mutation-registry.v4','sha256:32b9edaf4e718cfa55f87cc6b650f97480a09f00fbde35c10f1e5e23bc6eaa4c',1399,800),
    ('scac-mutation-registry.v5','sha256:314a4b108eaded1a00b7f604af93d44838b615fab79820d1a2c9d9d4b08fa6ca',1404,800),
    ('scac-mutation-registry.v6','sha256:afd27c13b68423dcaaeafc68c0c1ddc018452ef8d9e7cad5bb32cac4327d80d7',1408,800),
    ('scac-mutation-registry.v7','sha256:405a1bd7aa421b16ebd3d3fe7422a2525826dba563dffeb2dad5a6b90d12859b',1412,800),
    ('scac-mutation-registry.v8','sha256:56edcf25393a1c7b47985b9e2a272a8e7fcf0930709147ae823ca9b15290212e',1425,800)
  ) as x(registry_version,registry_digest,entry_count,source_entry_count) loop
    select * into actual from ops.scac_mutation_registry_version where registry_version=expected.registry_version;
    if actual.registry_digest is distinct from expected.registry_digest or actual.entry_count<>expected.entry_count or
       actual.source_entry_count<>expected.source_entry_count or not ops.scac_mutation_registry_seal_valid(expected.registry_version) then
      raise exception 'sealed historical SCAC registry % is missing or corrupt',expected.registry_version;
    end if;
  end loop;
end $history$;

alter function ops.scac_mutation_catalog_v8_current() rename to scac_mutation_catalog_v8_live_at_seal;
create or replace function ops.scac_mutation_registry_v8_seal_available()
returns boolean language sql stable security definer set search_path=pg_catalog,ops as $fn$
  select ops.scac_mutation_registry_seal_valid('scac-mutation-registry.v8')
$fn$;
create or replace function ops.scac_mutation_catalog_v8_current()
returns boolean language sql stable security definer set search_path=pg_catalog,ops as $fn$
  select ops.scac_mutation_catalog_v8_live_at_seal()
$fn$;
comment on function ops.scac_mutation_registry_v8_seal_available() is 'Exact immutable v8 registry seal; separate from whether the live catalog still equals v8.';
comment on function ops.scac_mutation_catalog_v8_current() is 'Historical v8 live-catalog validator; expected to become false after the v9 authority surface is installed.';

create or replace function ops.scac_mutation_catalog_v9_current()
returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,ops as $fn$
declare observed_count integer; observed_digest text;
begin
  with recursive connected(oid) as (select oid from pg_roles where rolname~'^carr_' and rolname<>'carr_ci' union select other.oid from connected c join pg_auth_members m on m.roleid=c.oid or m.member=c.oid join pg_roles other on other.oid=case when m.roleid=c.oid then m.member else m.roleid end where other.rolname<>'carr_ci' and not other.rolsuper),
  runtime_roles as (select r.oid,r.rolname from pg_roles r where r.oid in(select oid from connected) and not r.rolsuper),
  functions as (select p.oid,n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args,p.prosecdef,p.prokind,p.provolatile,p.proparallel,p.proconfig,p.proacl,p.proowner from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname not in ('pg_catalog','information_schema') and p.prokind in ('f','p')),
  capabilities as (select f.*,acl.grantee,acl.privilege_type,acl.is_grantable from functions f cross join lateral aclexplode(coalesce(f.proacl,acldefault('f',f.proowner))) acl),
  observed as (select 'db-function-acl:'||nspname||'.'||proname||'('||args||'):'||coalesce(r.rolname,'public')||':execute' ingress_key,jsonb_build_object('ingress_key','db-function-acl:'||nspname||'.'||proname||'('||args||'):'||coalesce(r.rolname,'public')||':execute','ingress_kind','db_function_acl','signature',nspname||'.'||proname||'('||args||')','security_definer',prosecdef,'function_kind',prokind,'volatility',provolatile,'parallel',proparallel,'config',coalesce(to_jsonb(proconfig),'[]'::jsonb),'grantee',coalesce(r.rolname,'public'),'privilege','execute','grantable',is_grantable) row from capabilities c left join pg_roles r on r.oid=c.grantee where prosecdef and privilege_type='EXECUTE' and grantee<>proowner and (grantee=0 or r.oid in(select oid from runtime_roles)))
  select count(*),'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(coalesce(jsonb_agg(row order by ingress_key collate "C", ops.scac_canonical_json(row) collate "C"),'[]'::jsonb)),'UTF8'),'sha256'),'hex') into observed_count,observed_digest from observed;
  if observed_count<>342 or observed_digest<>'sha256:57444b408258e9ec0a0dd8d2b8062cc6f6575e0b97cd0e9faebbb7ca322e17af' then return false; end if;
