  with recursive connected(oid) as (
    select oid from pg_roles where rolname~'^carr_' and rolname<>'carr_ci' and not rolcanlogin and not rolsuper union
    select other.oid from connected c join pg_auth_members m on m.roleid=c.oid or m.member=c.oid join pg_roles other on other.oid=case when m.roleid=c.oid then m.member else m.roleid end where other.rolname~'^carr_' and other.rolname<>'carr_ci' and not other.rolcanlogin and not other.rolsuper
  ), role_rows as (
    select 'db-role:'||r.rolname ingress_key,jsonb_build_object('ingress_key','db-role:'||r.rolname,'row_kind','role','role',r.rolname,'login',r.rolcanlogin,'inherit',r.rolinherit,'superuser',r.rolsuper,'create_role',r.rolcreaterole,'create_db',r.rolcreatedb,'replication',r.rolreplication,'bypass_rls',r.rolbypassrls) row from pg_roles r where r.oid in(select oid from connected)
  ), membership_rows as (
    select 'db-role-membership:'||role.rolname||':'||member.rolname ingress_key,jsonb_build_object('ingress_key','db-role-membership:'||role.rolname||':'||member.rolname,'row_kind','membership','role',role.rolname,'member',member.rolname,'admin_option',m.admin_option,'inherit_option',m.inherit_option,'set_option',m.set_option) row from pg_auth_members m join pg_roles role on role.oid=m.roleid join pg_roles member on member.oid=m.member where m.roleid in(select oid from connected) and m.member in(select oid from connected)
  ), ownership_rows as (
    select 'db-function-owner:'||n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||'):'||owner.rolname ingress_key,jsonb_build_object('ingress_key','db-function-owner:'||n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||'):'||owner.rolname,'row_kind','function_owner','signature',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')','owner',owner.rolname) row from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_roles owner on owner.oid=p.proowner where n.nspname not in ('pg_catalog','information_schema') and p.prokind in ('f','p') and owner.oid in(select oid from connected) and not owner.rolsuper and owner.rolname<>'neondb_owner' union all
    select 'db-relation-owner:'||n.nspname||'.'||c.relname||':'||owner.rolname,jsonb_build_object('ingress_key','db-relation-owner:'||n.nspname||'.'||c.relname||':'||owner.rolname,'row_kind','relation_owner','relation',n.nspname||'.'||c.relname,'relation_kind',c.relkind,'owner',owner.rolname) row from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_roles owner on owner.oid=c.relowner where n.nspname not in ('pg_catalog','information_schema') and c.relkind in ('r','p','v','m','f') and owner.oid in(select oid from connected) and not owner.rolsuper and owner.rolname<>'neondb_owner'
  ), observed as (select * from role_rows union all select * from membership_rows union all select * from ownership_rows)
  select count(*),'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(coalesce(jsonb_agg(row order by ingress_key collate "C", ops.scac_canonical_json(row) collate "C"),'[]'::jsonb)),'UTF8'),'sha256'),'hex') into observed_count,observed_digest from observed;
  if exists (select 1 from pg_auth_members m join pg_roles g on g.oid=m.roleid join pg_roles mem on mem.oid=m.member where mem.rolname~'^carr_' and (g.rolsuper or g.rolname~'^(neon_|pg_)')) then return false; end if;
  return observed_count=12 and observed_digest='sha256:eb650de73032466b46787f4a5826b60b100591657489a7990d9161e2d6588648';
end $fn$;

alter function ops.scac_policy_epoch_snapshot() rename to scac_policy_epoch_snapshot_v8;
create or replace function ops.scac_policy_epoch_snapshot()
returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,ops as $fn$
declare source jsonb; registry_ok jsonb;
begin
  source:=ops.scac_policy_epoch_snapshot_v3();
  if not (ops.scac_mutation_registry_seal_valid('scac-mutation-registry.v1') and
    ops.scac_mutation_registry_seal_valid('scac-mutation-registry.v2') and
    ops.scac_mutation_registry_seal_valid('scac-mutation-registry.v3') and
    ops.scac_mutation_registry_v4_seal_available() and
    ops.scac_mutation_registry_v5_seal_available() and
    ops.scac_mutation_registry_v6_seal_available() and
    ops.scac_mutation_registry_v7_seal_available() and
    ops.scac_mutation_registry_v8_seal_available()) then
    raise exception 'sealed historical SCAC mutation registry is unavailable or corrupt';
  end if;
  registry_ok:=ops.scac_mutation_registration_v9('sha256:398ddf5f86a46110518f7498af63782b65e047b9f624b798bf3c798058a79b4d','mcp-tool:standing-context');
  if coalesce((registry_ok->>'registered')::boolean,false) is not true then
    raise exception 'sealed SCAC mutation registry v9 is unavailable or corrupt: %',registry_ok->>'reason';
  end if;
  if not ops.scac_mutation_catalog_v9_current() then raise exception 'live SCAC v9 mutation catalog drifted'; end if;
  return jsonb_set(jsonb_set(source,'{registry_version}',to_jsonb('scac-mutation-registry.v9'::text)),
    '{registry_digest}',to_jsonb('sha256:398ddf5f86a46110518f7498af63782b65e047b9f624b798bf3c798058a79b4d'::text));
end $fn$;
create or replace function ops.scac_policy_epoch_chain_state()
returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,ops as $fn$
declare r ops.scac_policy_epoch%rowtype; expected bigint:=1; prior_digest text:=null; recomputed_source text; recomputed_epoch text; source jsonb; latest ops.scac_policy_epoch%rowtype;
begin
  for r in select * from ops.scac_policy_epoch order by epoch loop
    if r.epoch<>expected or (expected=1 and (r.previous_epoch is not null or r.previous_epoch_digest is not null))
       or (expected>1 and (r.previous_epoch<>expected-1 or r.previous_epoch_digest is distinct from prior_digest)) then
      return jsonb_build_object('valid',false,'reason','epoch_chain_gap_or_fork');
    end if;
    recomputed_source:='sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(jsonb_build_object(
      'registry_version',r.registry_version,'registry_digest',r.registry_digest,
      'doctrine_generation',r.doctrine_generation,'doctrine_projection_digest',r.doctrine_projection_digest,
      'rule_projection_digest',r.rule_projection_digest,'schema_applied_count',r.schema_applied_count,
      'schema_highest_migration',r.schema_highest_migration,'schema_ledger_digest',r.schema_ledger_digest)),'UTF8'),'sha256'),'hex');
    recomputed_epoch:=ops.scac_policy_epoch_digest(r.epoch,coalesce(r.previous_epoch,0),coalesce(r.previous_epoch_digest,'bootstrap'),recomputed_source,r.created_at);
    if not ((r.registry_version='scac-mutation-registry.v2' and r.registry_digest='sha256:6dc9f8353712e0f9ee9dcbc96d05b802631e420cfa698944c2b6401a11c6a9ff')
         or (r.registry_version='scac-mutation-registry.v3' and r.registry_digest='sha256:ace611250aaf2ffd7b96ca3195d20e9dc2697bbea555eadc7c661407e838cae7')
         or (r.registry_version='scac-mutation-registry.v4' and r.registry_digest='sha256:32b9edaf4e718cfa55f87cc6b650f97480a09f00fbde35c10f1e5e23bc6eaa4c')
         or (r.registry_version='scac-mutation-registry.v5' and r.registry_digest='sha256:314a4b108eaded1a00b7f604af93d44838b615fab79820d1a2c9d9d4b08fa6ca')
         or (r.registry_version='scac-mutation-registry.v6' and r.registry_digest='sha256:afd27c13b68423dcaaeafc68c0c1ddc018452ef8d9e7cad5bb32cac4327d80d7')
         or (r.registry_version='scac-mutation-registry.v7' and r.registry_digest='sha256:405a1bd7aa421b16ebd3d3fe7422a2525826dba563dffeb2dad5a6b90d12859b')
         or (r.registry_version='scac-mutation-registry.v8' and r.registry_digest='sha256:56edcf25393a1c7b47985b9e2a272a8e7fcf0930709147ae823ca9b15290212e')
         or (r.registry_version='scac-mutation-registry.v9' and r.registry_digest='sha256:398ddf5f86a46110518f7498af63782b65e047b9f624b798bf3c798058a79b4d'))
       or r.source_digest is distinct from recomputed_source or r.epoch_digest is distinct from recomputed_epoch
       or r.created_at>clock_timestamp()+interval '1 minute' then
      return jsonb_build_object('valid',false,'reason','epoch_digest_or_source_corrupt');
    end if;
    latest:=r; prior_digest:=r.epoch_digest; expected:=expected+1;
  end loop;
  if expected=1 then return jsonb_build_object('valid',false,'reason','epoch_ledger_unavailable'); end if;
  begin source:=ops.scac_policy_epoch_snapshot(); exception when others then
    return jsonb_build_object('valid',false,'reason','live_source_unavailable'); end;
  return jsonb_build_object('valid',true,'reason','valid','current_epoch',latest.epoch,
    'current_epoch_digest',latest.epoch_digest,'current_source_digest',latest.source_digest,
    'live_source_digest','sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(source),'UTF8'),'sha256'),'hex'),
    'registry_version',latest.registry_version,'registry_digest',latest.registry_digest,
    'schema_highest_migration',latest.schema_highest_migration);
end $fn$;
alter table ops.scac_policy_epoch drop constraint scac_policy_epoch_registry_version_digest_check;
alter table ops.scac_policy_epoch add constraint scac_policy_epoch_registry_version_digest_check check (
  (registry_version='scac-mutation-registry.v2' and registry_digest='sha256:6dc9f8353712e0f9ee9dcbc96d05b802631e420cfa698944c2b6401a11c6a9ff') or
  (registry_version='scac-mutation-registry.v3' and registry_digest='sha256:ace611250aaf2ffd7b96ca3195d20e9dc2697bbea555eadc7c661407e838cae7') or
  (registry_version='scac-mutation-registry.v4' and registry_digest='sha256:32b9edaf4e718cfa55f87cc6b650f97480a09f00fbde35c10f1e5e23bc6eaa4c') or
  (registry_version='scac-mutation-registry.v5' and registry_digest='sha256:314a4b108eaded1a00b7f604af93d44838b615fab79820d1a2c9d9d4b08fa6ca') or
  (registry_version='scac-mutation-registry.v6' and registry_digest='sha256:afd27c13b68423dcaaeafc68c0c1ddc018452ef8d9e7cad5bb32cac4327d80d7') or
  (registry_version='scac-mutation-registry.v7' and registry_digest='sha256:405a1bd7aa421b16ebd3d3fe7422a2525826dba563dffeb2dad5a6b90d12859b') or
  (registry_version='scac-mutation-registry.v8' and registry_digest='sha256:56edcf25393a1c7b47985b9e2a272a8e7fcf0930709147ae823ca9b15290212e') or
  (registry_version='scac-mutation-registry.v9' and registry_digest='sha256:398ddf5f86a46110518f7498af63782b65e047b9f624b798bf3c798058a79b4d'));
revoke all on function ops.scac_policy_epoch_snapshot(),ops.scac_policy_epoch_snapshot_v6(),ops.scac_policy_epoch_snapshot_v7(),ops.scac_policy_epoch_snapshot_v8(),ops.scac_mutation_catalog_v3_current(),ops.scac_mutation_catalog_v5_live_at_seal(),ops.scac_mutation_catalog_v5_current(),ops.scac_mutation_registry_v5_seal_available(),ops.scac_mutation_catalog_v6_live_at_seal(),ops.scac_mutation_catalog_v6_current(),ops.scac_mutation_registry_v6_seal_available(),ops.scac_mutation_catalog_v7_live_at_seal(),ops.scac_mutation_catalog_v7_current(),ops.scac_mutation_registry_v7_seal_available(),ops.scac_mutation_catalog_v8_live_at_seal(),ops.scac_mutation_catalog_v8_current(),ops.scac_mutation_registry_v8_seal_available(),ops.scac_mutation_catalog_v9_current() from public,carr_reader,carr_writer,carr_jobs,carr_authority;
comment on function ops.scac_policy_epoch_snapshot() is 'SIEP-18 successor snapshot: current policy epochs bind mutation registry v9 while historical v2/v3/v4/v5/v6/v7/v8 epochs remain immutable.';

create trigger scac_mutation_registry_version_sealed before insert or update or delete on ops.scac_mutation_registry_version for each row execute function ops.scac_mutation_registry_append_only();
create trigger scac_mutation_registry_entry_sealed before insert or update or delete on ops.scac_mutation_registry_entry for each row execute function ops.scac_mutation_registry_append_only();

-- Exact post-0467 grant binding; generated from disposable-DB readback.
create or replace function ops.scac_reference_monitor_state()
returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,ops as $fn$
declare grant_snapshot jsonb; mode_state jsonb; epoch_chain jsonb;
        latest ops.scac_policy_epoch%rowtype;
        registry ops.scac_mutation_registry_version%rowtype; missing_guards integer;
        unsupported_writable integer;
        grant_state text; guard_state text;
begin
  grant_snapshot:=ops.scac_runtime_dml_grant_snapshot();
  mode_state:=ops.scac_reference_monitor_mode();
  epoch_chain:=ops.scac_policy_epoch_chain_state();
  select * into latest from ops.scac_policy_epoch order by epoch desc limit 1;
  select * into registry from ops.scac_mutation_registry_version
    where registry_version=latest.registry_version;
  grant_state:=case when registry.registry_version='scac-mutation-registry.v9' and
    (grant_snapshot->>'entry_count')::integer=297 and
    grant_snapshot->>'grant_digest'='sha256:0f04a50d8bc65e2dcc765b1981ab1d5091c809570f0a773db3f5c6e2b9d43501'
    then 'current' else 'drifted_or_unbound' end;
  with recursive connected(oid) as (
    select oid from pg_roles where rolname in ('carr_writer','carr_jobs','carr_authority')
  ), writable as (
    select distinct c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace
    cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a
    where c.relkind in ('r','p') and a.grantee<>c.relowner
      and (a.grantee=0 or a.grantee in(select oid from connected))
      and a.privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE')
    union
    select distinct c.oid from pg_attribute att join pg_class c on c.oid=att.attrelid
    cross join lateral aclexplode(att.attacl) a
    where c.relkind in ('r','p') and att.attnum>0 and not att.attisdropped
      and a.grantee<>c.relowner
      and (a.grantee=0 or a.grantee in(select oid from connected))
      and a.privilege_type in ('INSERT','UPDATE')
  )
  select count(*) into missing_guards from writable w where not exists(
    select 1 from pg_trigger t where t.tgrelid=w.oid and not t.tgisinternal
      and t.tgfoid='ops.scac_reference_monitor_guard()'::regprocedure
      and (t.tgtype & 1)=1);
  with runtime_roles as (
    select oid from pg_roles where rolname in ('carr_writer','carr_jobs','carr_authority')
  ), unsupported as (
    select distinct c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace
    cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a
    where n.nspname not in ('pg_catalog','information_schema') and
      c.relkind in ('v','m','f') and a.grantee<>c.relowner and
      (a.grantee=0 or a.grantee in(select oid from runtime_roles))
      and a.privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE')
    union
    select distinct c.oid from pg_attribute att join pg_class c on c.oid=att.attrelid
    join pg_namespace n on n.oid=c.relnamespace
    cross join lateral aclexplode(att.attacl) a
    where n.nspname not in ('pg_catalog','information_schema') and
      c.relkind in ('v','m','f') and att.attnum>0 and not att.attisdropped and
      a.grantee<>c.relowner and
      (a.grantee=0 or a.grantee in(select oid from runtime_roles))
      and a.privilege_type in ('INSERT','UPDATE')
  ) select count(*) into unsupported_writable from unsupported;
  guard_state:=case when unsupported_writable>0 then 'unsupported_writable_relation'
    when missing_guards=0 then 'complete' else 'incomplete' end;
  return jsonb_build_object('schema_version','scac-reference-monitor-state.v1',
    'monitor_state',case when grant_state='current' and guard_state='complete'
      and coalesce((epoch_chain->>'valid')::boolean,false)
      and (epoch_chain->>'current_epoch')::bigint=latest.epoch
      and epoch_chain->>'current_epoch_digest'=latest.epoch_digest
      and mode_state->>'integrity_state'<>'invalid_fail_closed' then 'current'
      else 'unavailable' end,
    'grant_state',grant_state,'grant_digest',grant_snapshot->>'grant_digest',
    'guard_state',guard_state,'missing_guard_count',missing_guards,
    'unsupported_writable_relation_count',unsupported_writable,
    'mode',mode_state->>'mode','mode_integrity_state',mode_state->>'integrity_state',
    'policy_epoch_state',case when coalesce((epoch_chain->>'valid')::boolean,false)
      and (epoch_chain->>'current_epoch')::bigint=latest.epoch
      and epoch_chain->>'current_epoch_digest'=latest.epoch_digest
      then 'current' else 'invalid_or_unavailable' end,
    'policy_epoch',latest.epoch,'policy_epoch_digest',latest.epoch_digest,
    'registry_version',latest.registry_version,'registry_digest',latest.registry_digest,
    'direct_database_grant_cutover',false,'production_enforcement_active',false);
end $fn$;
